WITH unpacked AS (SELECT id, customer_id, created_at, coupon_codes, items, ship_to, FORALL(items, item -> item.qty <= 5) AS all_small_qty, ARRAY_CONTAINS(MAP_KEYS(attributes), 'gift') AS has_gift, SIZE(items) AS num_items, SIZE(FILTER(items, item -> item.qty >= 3)) AS bulk_lines FROM carts WHERE HOUR(created_at) BETWEEN 6 AND 12) SELECT *, SUM(bulk_lines) OVER (PARTITION BY customer_id) customer_id_sum_bulk_lines, NTILE(10) OVER (PARTITION BY customer_id ORDER BY bulk_lines DESC, id ASC) bulk_lines_bucket, SUM(num_items) OVER (ORDER BY created_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_num_items FROM unpacked;
